-- Loader generated by roblox-auth-panel
-- Script: scorpion.wtf

local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Read key from getgenv().KEY
local rawKey = rawget(getgenv(), "KEY")
if not rawKey or tostring(rawKey):gsub("%s+", "") == "" then
    if LocalPlayer then
        LocalPlayer:Kick("[Auth] Missing key! Set getgenv().KEY before executing.")
    end
    return
end

local key = tostring(rawKey):gsub("%s+", "")

-- Detect HWID across executors
local function getClientHWID()
    -- Try native gethwid() (Synapse X, etc.)
    if gethwid then
        local ok, hwid = pcall(gethwid)
        if ok and hwid and tostring(hwid) ~= "" then
            return tostring(hwid)
        end
    end

    -- Try RbxAnalyticsService client ID (unique per device)
    local analyticsId = ""
    pcall(function()
        analyticsId = game:GetService("RbxAnalyticsService"):GetClientId()
    end)

    -- Combine executor name + analytics ID
    if identifyexecutor then
        local ok, execName = pcall(identifyexecutor)
        if ok and execName then
            return tostring(execName) .. "_" .. tostring(analyticsId)
        end
    end

    if analyticsId and analyticsId ~= "" then
        return tostring(analyticsId)
    end

    return "UNKNOWN_HWID"
end

local hwid = getClientHWID()

-- Resolve HTTP request function for this executor
local httpRequest = (syn and syn.request)
    or (http and http.request)
    or http_request
    or request
    or (fluxus and fluxus.request)
    or (Axios and Axios.request)

if not httpRequest then
    if LocalPlayer then
        LocalPlayer:Kick("[Auth] Your executor does not support HTTP requests.")
    end
    return
end

-- Send validation request to auth server
local targetUrl = "https://sea-ry3a.onrender.com/api/validate"

local ok, response = pcall(function()
    return httpRequest({
        Url = targetUrl,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = HttpService:JSONEncode({
            key       = key,
            hwid      = hwid,
            script_id = "3c53f22a-5920-4ba1-9343-462d26da281e"
        })
    })
end)

if not ok or not response or not response.Body then
    if LocalPlayer then
        LocalPlayer:Kick("[Auth] Could not reach the authentication server.")
    end
    return
end

-- Compile and execute the returned Lua code
-- If the key is invalid the server returns a kick payload which also runs fine
local chunk, compileErr = loadstring(response.Body)
if not chunk then
    if LocalPlayer then
        LocalPlayer:Kick("[Auth] Script compile error: " .. tostring(compileErr))
    end
    return
end

local execOk, execErr = pcall(chunk)
if not execOk then
    warn("[Auth] Script execution error: " .. tostring(execErr))
end
